begin;
select no_plan();
select has_table('public','payment_receipts','metadados privados existem');
select is((select public from storage.buckets where id='payment-receipts'),false,'bucket privado');
select is((select file_size_limit from storage.buckets where id='payment-receipts'),5000000::bigint,'limite5MB no servidor');
select is((select allowed_mime_types from storage.buckets where id='payment-receipts'),array['image/jpeg','image/png','application/pdf'],'tipos limitados no bucket');
insert into auth.users(id) values('81000000-0000-0000-0000-000000000001'),('81000000-0000-0000-0000-000000000002');
insert into public.profiles values('81000000-0000-0000-0000-000000000001','owner'),('81000000-0000-0000-0000-000000000002','driver');
insert into public.customers(id,name,address,weekday,position) values('82000000-0000-0000-0000-000000000001','Comprovante fictício','Rua fictícia',3,1);
insert into public.payments(id,customer_id,amount_cents,received_at,method,actor_id) values('83000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001',10000,now(),'pix','81000000-0000-0000-0000-000000000001');
select is(public.reserve_payment_receipt('84000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000001.png','image/png',67,repeat('a',64),'81000000-0000-0000-0000-000000000001'),'pending','tentativa vinculada antes de subir bytes');
select is(public.reserve_payment_receipt('84000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000001.png','image/png',67,repeat('b',64),'81000000-0000-0000-0000-000000000001'),'conflict','mesma tentativa com bytes diferentes rejeitada');
select throws_ok($$select public.reserve_payment_receipt('84000000-0000-0000-0000-000000000099','83000000-0000-0000-0000-000000000099','83000000-0000-0000-0000-000000000099/84000000-0000-0000-0000-000000000099.png','image/png',1,repeat('a',64),'81000000-0000-0000-0000-000000000001')$$,'22023','INVALID_RECEIPT','pagamento inexistente recusado mesmo com path válido');
select throws_ok($$select public.complete_payment_receipt('84000000-0000-0000-0000-000000000001')$$,'22023','OBJECT_NOT_FOUND','vínculo final exige objeto real');
insert into storage.objects(bucket_id,name,metadata) values('payment-receipts','83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000001.png','{"mimetype":"image/png","size":67}');
select is(jsonb_array_length(public.get_payment_receipt_orphans()),1,'objeto pendente listado órfão');
select public.complete_payment_receipt('84000000-0000-0000-0000-000000000001');
select is(jsonb_array_length(public.get_payment_receipt_orphans()),0,'objeto vinculado não é órfão');
select is(public.mark_receipt_orphan_removed('83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000001.png'),false,'limpeza não remove objeto vinculado');
select public.reserve_payment_receipt('84000000-0000-0000-0000-000000000002','83000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000002.pdf','application/pdf',20,repeat('b',64),'81000000-0000-0000-0000-000000000001');
select is(public.mark_receipt_orphan_removed('83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000002.pdf'),true,'limpeza encerra tentativa pendente');
select is(public.mark_receipt_orphan_removed('83000000-0000-0000-0000-000000000001/84000000-0000-0000-0000-000000000002.pdf'),true,'limpeza repetida idempotente');
select throws_ok($$select public.complete_payment_receipt('84000000-0000-0000-0000-000000000002')$$,'PT409','RECEIPT_REMOVED','vínculo atrasado após limpeza rejeitado');
select set_config('request.jwt.claim.sub','81000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is((select count(*) from public.payment_receipts),1::bigint,'dona lê somente anexos prontos');
select is((select count(*) from storage.objects where bucket_id='payment-receipts'),1::bigint,'dona lê arquivo vinculado');
select throws_ok($$insert into storage.objects(bucket_id,name) values('payment-receipts','arbitrary.png')$$,'42501',null,'upload direto da dona negado: exige servidor validar bytes');
select throws_ok($$insert into public.payment_receipts(id,payment_id,object_path,mime_type,size_bytes,sha256,actor_id) values(gen_random_uuid(),'83000000-0000-0000-0000-000000000001','fake','image/png',1,repeat('a',64),'81000000-0000-0000-0000-000000000001')$$,'42501',null,'metadados não graváveis diretamente');
select throws_ok($$select public.complete_payment_receipt('84000000-0000-0000-0000-000000000001')$$,'42501',null,'RPC interna inacessível à dona');
select set_config('request.jwt.claim.sub','81000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.payment_receipts),0::bigint,'motorista não lê anexos');
select is((select count(*) from storage.objects where bucket_id='payment-receipts'),0::bigint,'motorista não lê bytes');
reset role;
set local role anon;
select throws_ok($$select * from public.payment_receipts$$,'42501',null,'anônimo não lê metadados');
select is((select count(*) from storage.objects where bucket_id='payment-receipts'),0::bigint,'anônimo não lê bytes');
reset role;
select is((select amount_cents from public.payments where id='83000000-0000-0000-0000-000000000001'),10000::bigint,'comprovante/limpeza não altera recebimento');
select * from finish();
rollback;
